import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# C++ kernel for cumulative product (naive O(N^2) per thread).
# Each thread computes the product of all elements from index 0 up to its own idx.
# ----------------------------------------------------------------------
cumprod_kernel_cpp = """
__global__ void cumprod_kernel(const float* input, float* output, int total_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        float prod = 1.0f;
        for (int k = 0; k <= idx; ++k) {
            prod *= input[k];
        }
        output[idx] = prod;
    }
}
"""

# ----------------------------------------------------------------------
# CUDA wrapper that launches the kernel.
# It takes a tensor `x` and an integer `dim`. The implementation is simplified
# (flattens the tensor for demonstration; in practice you would handle multi‑dimensional indexing).
# ----------------------------------------------------------------------
cumprod_cuda_source = """
torch::Tensor cumprod_cuda(torch::Tensor x, int dim) {
    auto size = x.numel();
    float* out_ptr = (float*)x.data_ptr<float>(); // placeholder for output buffer

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    cumprod_kernel<<<num_blocks, block_size>>>(x.data_ptr<float()>, out_ptr, size);

    return x; // In a full implementation you would copy the result back to `out_ptr`.
}
"""

# ----------------------------------------------------------------------
# Create custom CUDA operator via load_inline.
# The function name is "cumprod" and it exposes method "cumprod_cuda".
# ----------------------------------------------------------------------
cumprod = load_inline(
    name="cumprod",
    cpp_sources=cumprod_kernel_cpp,
    cuda_sources=cumprod_cuda_source,
    functions=["cumprod_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self, dim: int) -> None:
        super().__init__()
        self.dim = dim
        self.cumprod = cumprod

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.cumprod(x, self.dim)
